# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping handoff load from an unauthenticated caller" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:refused_load_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => refused_load_token
    ) { example.run }
  end

  def refused_load_table_rows
    %w[entries reservations invoice_operations audit_events idempotency_receipts].index_with do |table|
      ApplicationRecord.connection.select_rows("SELECT * FROM #{table} ORDER BY 1, 2")
    end
  end

  # "Every handoff endpoint refuses a caller without service credentials"
  # A 401 sent after the replace ran would still pass a status-only check.
  it "refuses a load from a caller without the service token and leaves the tables unchanged" do
    Timekeeping::Admission.fence!
    get "/internal/v1/handoff/checkpoint", headers: { "Authorization" => "Bearer #{refused_load_token}" }
    expect(response.status).to eq(200)
    empty_checkpoint = response.body

    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note: "Kept", bill_status: "unbilled", source: "manual", source_metadata: {})
    before = refused_load_table_rows
    owner_token = mint_token({ sub: 7, company_id: 1, role: "owner" })

    [nil, "Bearer #{owner_token}", "Bearer #{refused_load_token}x"].each do |authorization|
      headers = { "Content-Type" => "application/json" }
      headers["Authorization"] = authorization if authorization
      put "/internal/v1/handoff/checkpoint", params: empty_checkpoint, headers: headers

      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])
    end
    expect(refused_load_table_rows).to eq(before)
  end
end
